    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.multiplexerEClass, source, new String[]{"documentation", "A multiplexer is used to define variable parts within a PDU that may carry different signals. \r\nThe receivers of such a PDU can determine which signals are transmitted by evaluating the selector field, which carries a unique selector code for each sub-part.  "});
        this.addAnnotation((ENamedElement)this.getMultiplexer_Datas(), source, new String[]{"documentation", "According to the value of the selector field some parts of the PDU have a different layout. These parts of the PDU that can contain different signals are called dynamic part. "});
        this.addAnnotation((ENamedElement)this.getMultiplexer_SelectorFieldByteOrder(), source, new String[]{"documentation", "This parameter defines the byte order of the selector field. \r\n The byte ordering \"Little Endian\" (MostSignificantByteLast) and \"Big Endian\" (MostSignificantByteFirst) can be selected. \r\nThe value of this attribute impacts the absolute position of the selector field into the PDU."});
        this.addAnnotation((ENamedElement)this.getMultiplexer_SelectorFieldLength(), source, new String[]{"documentation", "The size in bits of the selector field shall be configurable in a range of one bit and eight bits. "});
        this.addAnnotation((ENamedElement)this.getMultiplexer_SelectorFieldStartPosition(), source, new String[]{"documentation", "This parameter is necessary to describe the position of the selector field within the PDU.\r\n \r\nIt denotes the least significant bit for \"Little Endian\" and the most significant bit for \"Big Endian\" (see the description of the selectorFieldByteOrder attribute)."});
        this.addAnnotation((ENamedElement)this.subPDUEClass, source, new String[]{"documentation", "A multiplexed PDU consists of a static part and a dynamic part, where the static part consists of zero or more signals and  the dynamic part consists of the selector field and one or more signals. Each part of a multiplexed PDU, the static part and the different dynamic parts, are described as a SubPDU."});
        this.addAnnotation((ENamedElement)this.getSubPDU_DynamicSubPDUTimings(), source, new String[]{"documentation", "This relationship is only valid for the dynamic part of the PDU. This relationship allows to define a timing for a SubPdu with a certain selectorFieldCode. "});
        this.addAnnotation((ENamedElement)this.getSubPDU_IncludedSignals(), source, new String[]{"documentation", "Definition of the signals included in the SubPDU with their position. All signals included must have the same transmitter (as specified in the cluster signal). "});
        this.addAnnotation((ENamedElement)this.getSubPDU_SelectorFieldCode(), source, new String[]{"documentation", "The selector field is part of a multiplexed PDU. It consists of contiguous bits. The value of the selector field selects the layout of the multiplexed part of the PDU. This attribute is only valid for the dynamic part of the PDU."});
        this.addAnnotation((ENamedElement)this.getSubPDU_StartPosition(), source, new String[]{"documentation", "The position of the static and the dynamic part of the multiplexer in the PDU. "});
        this.addAnnotation((ENamedElement)this.getSubPDU_SubPDUSize(), source, new String[]{"documentation", "The size of the SubPDU in bits. The size is limited by the PDUSize."});
        this.addAnnotation((ENamedElement)this.signalPositionEClass, source, new String[]{"documentation", "The signal position defines which system signal is transmitted at which position within the aggregating PDU. The SignalPosition must be defined within a PDU or a SubPDU."});
        this.addAnnotation((ENamedElement)this.getSignalPosition_PackingByteOrder(), source, new String[]{"documentation", "This parameter defines the order of the bytes of the signal are packed into the PDU. The byte ordering \"Little Endian\" (MostSignificantByteLast) and \"Big Endian\" (MostSignificantByteFirst) can be selected. \r\nThe value of this attribute impacts the absolute position of the signal into the PDU (see the startPosition attribute description).\r\n"});
        this.addAnnotation((ENamedElement)this.getSignalPosition_StartPosition(), source, new String[]{"documentation", "This parameter is necessary to describe the position of a signal within a PDU or SubPDU.\r\nIt denotes the least significant bit for \"Little Endian\" and the most significant bit for \"Big Endian\" packed signals within the PDU (see the description of the packingByteOrder attribute).\r\n\r\nBits within the PDU are counted as follows (see the OSEK COM v3.0.3 specification) :\r\n      Bit 0 corresponds to Byte 0 Bit 0\r\n      Bit 1 corresponds to Byte 0 Bit 1\r\n      .....\r\n      Bit 8 corresponds to Byte 1 Bit 0\r\n      etc.\r\n\r\nPlease note that the way the bytes will be actually sent on the bus does not impact this representation: they will always be seen by the software as a byte array. \r\nNote also that the absolute position of the signal in the PDU is then determined by the definition of the packingByteOrder attribute of the signal.\r\n"});
        this.addAnnotation((ENamedElement)this.getSignalPosition_SystemSignal(), source, new String[]{"documentation", "Reference to the system signal that shall be transported at this position in the frame."});
        this.addAnnotation((ENamedElement)this.pduTypeEClass, source, new String[]{"documentation", "PDUType defines the structure of a PDU."});
        this.addAnnotation((ENamedElement)this.getPDUType_IncludedSignals(), source, new String[]{"documentation", "Definition of the signals included in the PDU with their position. All signals included must have the same transmitter (as specified in the cluster signal). "});
        this.addAnnotation((ENamedElement)this.getPDUType_MultiplexerDynamicPart(), source, new String[]{"documentation", "Multiplexing is used to transport varying signals at the same position of a single PDU. According to the value of the selector field some parts of the PDU have a different layout. These parts of the PDU that can contain different signals are called dynamic part. "});
        this.addAnnotation((ENamedElement)this.getPDUType_MultiplexerStaticPart(), source, new String[]{"documentation", "Some parts of the PDU may be the same regardless of the selector field. Such a part is called static part. It is  possible that the static part of a PDU is zero bits long (only the dynamic part is defined)."});
        this.addAnnotation((ENamedElement)this.getPDUType_NeedsUpdateIndication(), source, new String[]{"documentation", "Boolean value that defines whether a UpdateIndicationBit has to be defined in the Frame that is associated with this PDUType. If this attribute is omitted, no UpdateIndication bit will be added to the Frame. \r\nThe AUTOSAR FlexRay Interface explicitly defines a location for the update\r\nbit that relates to a PDU."});
        this.addAnnotation((ENamedElement)this.getPDUType_PDULength(), source, new String[]{"documentation", "The size of the PDU in bits. The size is limited by the frameLength."});
    }

